// Where a finding goes: one single definition, for everyone.
//
// There used to be two, which did not say the same thing. `CountFindings`
// classified on `Source` alone and sent everything else to the severity
// counters; the security view classified on `Source` plus `PkgName` plus
// `Match`. Three entries told them apart — a trivy finding with no
// `PkgName`, an unknown source, a trivy finding carrying a `Match` — and
// each produced a finding counted in the header's CVE bar but absent from
// every tab, so invisible in the table. Same family as D24, D25 and D26:
// two copies of one rule, one place to update.
//
// Classification is now done on the source and nothing else, which required
// giving Trivy secrets their own source (`trivy-secret`) instead of being
// recognized by the presence of a `Match`.

// The sources a scanner can produce. A source missing from this list is a
// programming defect, not user input: `Categorize` classifies it as a
// vulnerability, which keeps it visible in the CVE tab rather than making it
// disappear.
const (
	SourceTrivy          = "trivy"           // vulnerabilities
	SourceTrivySecret    = "trivy-secret"    // secrets detected by Trivy
	SourceTrivyLicense   = "trivy-license"   // licenses
	SourceTrivyMisconfig = "trivy-misconfig" // IaC misconfigurations
	SourceGitleaks       = "gitleaks"        // secrets detected by Gitleaks
	SourcePlumber        = "plumber"         // pipeline security score (§3.42)
)

// Category is the family a finding belongs to: a tab in the results view,
// and a counter on `Result`.
type Category int

const (
	CategoryVulnerability Category = iota
	CategorySecret
	CategoryLicense
	CategoryMisconfiguration
	CategoryCIScore
)

// Categorize returns the family a finding belongs to.
//
// It is the only function that decides, and `Result.CountFindings` as well
// as the security view's tabs go through it.
func Categorize(f Finding) Category {
	switch f.Source {
	case SourceGitleaks, SourceTrivySecret:
		return CategorySecret
	case SourceTrivyLicense:
		return CategoryLicense
	case SourceTrivyMisconfig:
		return CategoryMisconfiguration
	case SourcePlumber:
		return CategoryCIScore
	default:
		return CategoryVulnerability
	}
}
package scan

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"os/exec"
	"strings"
)

// toolCmd is one subprocess invocation: the binary and the arguments handed to
// it. Building it is pure, which is what makes the argument surface — the part
// that decides what a scanner is actually asked to do — testable without a
// scanner installed.
//
// It is also what the UI displays. Deriving the shown command and the executed
// one from the same value is the point: the two used to be built separately and
// had drifted (§1.3 D19).
type toolCmd struct {
	Name string
	Args []string
	// Env is the child's whole environment when it is not nil, os.Environ()
	// plus what the caller added. It exists so a credential can reach a tool
	// without going through argv, which is readable from the process list —
	// the arrangement the clone already uses for http.extraHeader (§3.16).
	//
	// String() never renders it: the invocation is logged and shown in the UI.
	Env []string

	// Dir is the working directory the tool runs in, when it has one.
	//
	// It exists for plumber, whose `analyze` takes **no path argument**: it
	// works on the current directory. Without this the tool ran in whatever
	// directory DevDesk was launched from and reported
	// `--project is required (could not auto-detect from git remote)` — a
	// failure about a repository nobody had asked it to look at. Trivy and
	// Gitleaks take their target in argv and set nothing here.
	Dir string
}

// String renders the invocation as a shell command line, for logs and for the
// command the UI shows next to a scan.
func (c toolCmd) String() string {
	if c.Name == "" {
		return ""
	}
	line := strings.Join(append([]string{c.Name}, c.Args...), " ")
	// The directory is part of what the command means when the tool takes no
	// path: a logged invocation that cannot be re-run says less than it looks
	// like it does.
	if c.Dir != "" {
		return "cd " + c.Dir + " && " + line
	}
	return line
}

// exitError reports a tool that ran and exited non-zero. The code matters:
// both scanners use a non-zero exit to mean "I found something" rather than
// "I failed" — trivy for vulnerabilities, gitleaks for secrets — so callers
// have to tell the two apart.
type exitError struct {
	Code   int
	Stderr string
}

func (e *exitError) Error() string {
	if e.Stderr != "" {
		return fmt.Sprintf("exit status %d: %s", e.Code, strings.TrimSpace(e.Stderr))
	}
	return fmt.Sprintf("exit status %d", e.Code)
}

// commandRunner is the seam every subprocess in this package passes through.
//
// The package drives trivy and gitleaks as external processes, which makes it
// untestable without both installed and a repository to point them at. Routing
// through this interface lets tests exercise the argument building, the
// exit-code handling and the output parsing — where the defects live — against
// canned output.
type commandRunner interface {
	// Run executes tc and returns what it wrote to stdout. Lines written to
	// stderr are forwarded to progressFn as they arrive, which is how Trivy
	// reports its database download. A tool that runs and exits non-zero
	// returns its stdout along with an *exitError.
	Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error)
}

// cliRunner is the production commandRunner: it shells out to the real tools.
type cliRunner struct{}

func (cliRunner) Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error) {
	cmd := exec.CommandContext(ctx, tc.Name, tc.Args...) //nolint:gosec // name is one of trivy/gitleaks/plumber/docker
	cmd.Env = tc.Env                                     // nil inherits this process's environment, which is the default
	cmd.Dir = tc.Dir                                     // empty runs in DevDesk's own working directory

	var stdout bytes.Buffer
	cmd.Stdout = &stdout

	// Stderr is consumed two ways: streamed to progressFn while the tool runs,
	// and kept so a failure can be reported with the tool's own diagnostic.
	var stderr bytes.Buffer
	if progressFn != nil {
		pipe, err := cmd.StderrPipe()
		if err == nil {
			done := make(chan struct{})
			go func() {
				defer close(done)
				sc := bufio.NewScanner(pipe)
				for sc.Scan() {
					line := strings.TrimSpace(sc.Text())
					if line == "" {
						continue
					}
					stderr.WriteString(line)
					stderr.WriteByte('\n')
					progressFn(line)
				}
				// A read failure on the progress pipe is not a scan failure:
				// the report comes back on stdout, and the tool's exit code
				// says whether it succeeded. Dropping the rest of the progress
				// is the whole consequence.
				_ = sc.Err()
			}()
			if err := cmd.Start(); err != nil {
				return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
			}
			<-done // drain stderr before Wait closes the pipe
			return finish(tc.Name, cmd, &stdout, &stderr)
		}
	}

	cmd.Stderr = &stderr
	if err := cmd.Start(); err != nil {
		return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
	}
	return finish(tc.Name, cmd, &stdout, &stderr)
}

// finish waits for the tool and only then reads what it wrote.
//
// The order is the point, and it is not a style preference: os/exec fills the
// output buffers from goroutines it owns, and only Wait guarantees they are
// done. Reading the buffer in the same expression as Wait — which is what
// `return stdout.Bytes(), waitErr(..., cmd.Wait(), ...)` does, since operands
// are evaluated before the call — snapshots it while it is still empty, and
// every scan comes back with no findings.
func finish(name string, cmd *exec.Cmd, stdout, stderr *bytes.Buffer) ([]byte, error) {
	err := cmd.Wait()
	return stdout.Bytes(), waitErr(name, err, stderr.String())
}

// waitErr turns a non-zero exit into an *exitError carrying the code, and
// leaves anything else (a killed process, a broken pipe) as it is.
func waitErr(name string, err error, stderr string) error {
	if err == nil {
		return nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		if stderr == "" {
			stderr = string(exitErr.Stderr)
		}
		return &exitError{Code: exitErr.ExitCode(), Stderr: stderr}
	}
	return fmt.Errorf("%s failed: %w", name, err)
}

// runner is swapped by tests. Production code never reassigns it, so the
// package stays safe to call concurrently; tests that swap it must not run in
// parallel.
var runner commandRunner = cliRunner{}

package scan

import (
	"context"
	"errors"
	"fmt"
	"os"

	"github.com/anthnel/devdesk/internal/engine"
)

// plumber reads a repository's CI configuration — GitHub workflows, .gitlab-ci
// — through a Rego policy engine and grades it: a letter from A to E, points
// out of 100, and the issues that explain them (§3.42).
//
// Everything here is measured on plumber 0.4.40 and 0.4.42, by real runs. The
// section it implements was twice wrong about this tool from reading its
// documentation, so nothing below is inferred.

// Exit codes. Four, not three: `3` says the analysis ran on incomplete data and
// the score is withheld, and it is the one that matters most here — it maps
// exactly onto the `?` state of the CI column, without anyone having to read
// dataCollectionDegraded out of the JSON to find out.
const (
	plumberGateFailed    = 1 // a score exists and is below --min-points
	plumberRuntimeError  = 2 // no token, bad config, unreachable host, no repository
	plumberScoreWithheld = 3 // it ran, and says it cannot conclude
)

// plumberConfigMount is where a configured rules file is mounted inside the
// container, on §3.50's model: the argument plumber sees is never the host path.
//
// The container root is free of everything except /plumber, the binary itself
// (checked on getplumber/plumber). The repository is mounted at
// containerScanPath, so no file of it can land beside this one.
const plumberConfigMount = "/plumber.yaml"

// plumberSafeDirectory is what lets a containerised plumber read the mounted
// repository at all.
//
// The image runs as uid 65532, so git refuses the mount with `fatal: detected
// dubious ownership in repository at '/scan'` and plumber answers *could not
// determine the provider: not in a git repository*. Passing it through the
// environment rather than a config file is what keeps the mount read-only and
// the user non-root; `--user` is not portable to Windows hosts. Measured, not
// deduced: `--provider` alone does **not** lift it.
var plumberSafeDirectory = []string{
	"-e", "GIT_CONFIG_COUNT=1",
	"-e", "GIT_CONFIG_KEY_0=safe.directory",
	"-e", "GIT_CONFIG_VALUE_0=" + containerScanPath,
}

// PlumberOptions is what one plumber run needs beyond the tool itself.
type PlumberOptions struct {
	// Provider is the forge this context targets, declared rather than sniffed
	// from the remote: config.ForgeGitLab or config.ForgeGitHub.
	Provider string
	// Branch is the repository's current branch. It is passed and the failure
	// accepted: a score describing the default branch when the user is looking
	// at another one would be right about something they did not ask about.
	// The flag has no effect on the GitHub local path, which reads the tree.
	Branch string
	// ConfigPath is scan.plumber_config, already absolute (config.ExpandPaths).
	ConfigPath string
	// Token is the context's forge token. It reaches plumber through the
	// environment, never argv, which is readable from the process list.
	Token string
	// GitLabURL is the instance to talk to on the GitLab path.
	GitLabURL string
}

// plumberArgs builds the invocation.
//
// The JSON leaves by two different routes, and the asymmetry is measured rather
// than chosen: in a container `--output /dev/stdout` works, and for a native
// Windows binary it writes nothing at all — there is no such path. So the
// binary mode writes to a file the caller passes in and deletes.
//
// `--print=false` is what keeps stdout pure JSON: the human report and the
// score banner both go there otherwise. The tool's own logs go to stderr, which
// is where progressFn reads them.
func plumberArgs(target string, tool ToolSpec, opts PlumberOptions, outPath string) toolCmd {
	docker := tool.Source == ToolSourceContainer

	configFlag := opts.ConfigPath
	if docker && opts.ConfigPath != "" {
		configFlag = plumberConfigMount
	}

	options := []string{"analyze", "--score", "--print=false", "--output", outPath}
	if opts.Provider != "" {
		options = append(options, "--provider", opts.Provider)
	}
	if opts.Branch != "" {
		options = append(options, "--branch", opts.Branch)
	}
	if opts.GitLabURL != "" {
		options = append(options, "--gitlab-url", opts.GitLabURL)
	}
	if opts.ConfigPath != "" {
		options = append(options, "--config", configFlag)
	}

	if docker {
		args := []string{"run", "--rm", "-v", target + ":" + containerScanPath + ":ro"}
		if opts.ConfigPath != "" {
			// Before the image name: everything after it is plumber's own argv.
			args = append(args, "-v", opts.ConfigPath+":"+plumberConfigMount+":ro")
		}
		args = append(args, plumberSafeDirectory...)
		args = append(args, plumberTokenEnv(opts)...)
		args = append(args, "-w", containerScanPath, plumberImage(tool.Image))
		return toolCmd{Name: engine.Current().Binary, Args: append(args, options...)}
	}

	// Dir, not an argument: `analyze` works on the current directory and takes
	// no path. The container gets the same thing through -w.
	return toolCmd{Name: plumberBinary(tool), Args: options, Dir: target}
}

// plumberTokenEnv passes the context's token to a containerised plumber.
//
// The variable differs by forge, and naming both would send a GitLab token to
// GitHub on a repository that answers to neither. An empty token declares
// nothing rather than an empty variable: plumber treats "set but empty" as an
// attempt, and its diagnostic is then about a rejected credential rather than
// about a missing one.
func plumberTokenEnv(opts PlumberOptions) []string {
	if opts.Token == "" {
		return nil
	}
	name := "GH_TOKEN"
	if opts.Provider == providerGitLab {
		name = "GITLAB_TOKEN"
	}
	return []string{"-e", name + "=" + opts.Token}
}

func plumberImage(image string) string {
	if image == "" {

	return wrapTrivy(args, target, targetType, tool, server, false), nil
}

// wrapTrivy turns tool arguments into the invocation to run: either trivy
// directly, or docker run with the target mounted and the tool arguments
// appended after the image.
//
// noSocket says the scan reads its image from the registry, so the engine
// socket is not mounted: nothing would use it.
func wrapTrivy(args []string, target string, targetType TargetType, tool ToolSpec, server string, noSocket bool) toolCmd {
	if tool.Source != ToolSourceContainer {
		return toolCmd{Name: trivyBinary(tool), Args: append(args, target)}
	}

	engineArgs := []string{"run", "--rm"}
	if targetType == TargetDirectory {
		engineArgs = append(engineArgs, "-v", target+":"+containerScanPath+":ro")
		args = append(args, containerScanPath)
	} else {
		if server == "" && !noSocket {
			if mount, ok := socketMount(tool.HostSocket); ok {
				engineArgs = append(engineArgs, "-v", mount)
			}
		}
		args = append(args, target)
	}
	engineArgs = append(engineArgs, trivyImage(tool.Image))
	return toolCmd{Name: engine.Current().Binary, Args: append(engineArgs, args...)}
}

// trivyBinary is what to exec for a binary-source scan: the resolved path when
// detection found one, else the plain name. The fallback keeps the pure arg
// builders usable from tests that never ran detection.
func trivyBinary(tool ToolSpec) string {
	if tool.Binary != "" {

	if image == "" {
		return DefaultPlumberImage
	}
	return image
}

func plumberBinary(tool ToolSpec) string {
	if tool.Binary != "" {
		return tool.Binary
	}
	return "plumber"
}

// providerGitLab and providerGitHub are the values --provider takes. They are
// stated here as well as in internal/config because scan must not import a
// forge backend and config must not be the authority on a tool's flags;
// TestThePlumberProviderVocabularyMatchesTheConfig holds the two in step, the
// same arrangement as the registry provider names.
const (
	providerGitLab = "gitlab"
	providerGitHub = "github"
)

// PlumberReport is what one run says about a repository, beyond its findings.
type PlumberReport struct {
	// Score is the letter, empty when it was withheld.
	Score string
	// Points is finalPoints out of 100, and it is a float: a score is a
	// weighted sum, so a whole number is the exception rather than the shape.
	Points float64
	// Withheld reports a run that could not conclude — exit 3, and
	// dataCollectionDegraded in the JSON. Its letter must never be shown: a
	// degraded run of the fixture reads B/79 where the complete run reads E/30,
	// because a control that did not run found nothing.
	Withheld bool
	// Reasons is why, when it was withheld.
	Reasons []string
	// CIMissing reports a repository with no pipeline at all, which is not a
	// bad score.
	CIMissing bool
	// Findings are the issues, with their severity joined on from the score
	// block.
	Findings []Finding
}

// RunPlumber executes plumber and returns what it found.
func RunPlumber(ctx context.Context, target string, tool ToolSpec, opts PlumberOptions, progressFn func(string)) (*PlumberReport, error) {
	if err := checkPlumberConfig(opts.ConfigPath); err != nil {
		return nil, err
	}

	outPath, read, cleanup, err := plumberOutput(tool)
	if err != nil {
		return nil, err
	}
	defer cleanup()

	cmd := plumberArgs(target, tool, opts, outPath)
	if tool.Source != ToolSourceContainer && opts.Token != "" {
		cmd.Env = plumberBinaryEnv(opts)
	}

// Result represents the aggregated scan results
type Result struct {
	Target      string         `json:"target"`
	TargetType  TargetType     `json:"target_type"`
	StartTime   time.Time      `json:"start_time"`
	EndTime     time.Time      `json:"end_time"`
	Duration    time.Duration  `json:"duration"`
	Counts      SeverityCounts `json:"counts"`       // CVE counts by severity
	SecretCount int            `json:"secret_count"` // Total secrets found (gitleaks + trivy)
	// SecretsScanned tells "no secret was found" apart from "no one looked".
	// A secrets stage can fail to run for three reasons — the option is off,
	// the tool is missing, the stage errored — and in all three cases a
	// counter stuck at zero would say "this target is clean" about a scan
	// that never looked at it. It is the same principle as missingToolErrors
	// below (§1.3 D20), carried through to what the views display.
	SecretsScanned bool      `json:"secrets_scanned"`
	LicenseCount   int       `json:"license_count"`   // Total license issues found
	MisconfigCount int       `json:"misconfig_count"` // Total misconfigurations found
	CIIssueCount   int       `json:"ci_issue_count"`  // Total CI-configuration issues found
	Findings       []Finding `json:"findings"`
	Errors         []string  `json:"errors,omitempty"`

	// CIScanned tells "this pipeline was graded" apart from "no one looked",
	// exactly as SecretsScanned does one field up: the stage can fail to run
	// four ways — the option is off, plumber is absent, the repository is not
	// this context's forge, or the run errored — and in all four a letter would
	// be a claim nobody made.
	CIScanned bool `json:"ci_scanned"`
	// CIScore is the letter, and it is **empty on a withheld run**. plumber
	// writes one anyway, and it flatters: on the reference fixture the degraded
	// run reads B/79 where the complete run reads E/30, because a control that
	// did not run found nothing.
	CIScore string `json:"ci_score,omitempty"`
	// CIPoints is finalPoints out of 100, a float — see PlumberReport.Points.
	CIPoints float64 `json:"ci_points,omitempty"`
	// CIWithheld is a run that could not conclude, and CIReasons is what it
	// could not collect. Together they are the `?` of the CI column.
	CIWithheld bool     `json:"ci_withheld,omitempty"`
	CIReasons  []string `json:"ci_reasons,omitempty"`
	// CIMissing is a repository with no pipeline at all, which is not a bad
	// score — it is the absence of the thing being scored.
	CIMissing bool `json:"ci_missing,omitempty"`
}

// CIVerdict is what this scan can say about the pipeline's grade, for the cache
// and the column: nil when nothing graded it, the letter otherwise.
//
// It is the only calculation of the verdict, on SecretVerdict's model and for
// its reason — there were two of those, written the same way, and both became
// wrong on the same day (§3.12). A withheld run answers nil rather than its
// letter: nobody concluded, so nobody may be quoted.
func (r *Result) CIVerdict() *string {
	if !r.CIScanned || r.CIWithheld || r.CIScore == "" {
		return nil
	}
	score := r.CIScore
	return &score
}

// recordStageError puts a stage's failure where it can be found.
//
// The result carries it for the caches and the callers; the **log** carries the
// detail, because the views do not print a tool's stderr any more — Rule 128's
// arrangement, which this package was not part of: a stage that failed appended
// to result.Errors and logged nothing, so the only copy of the reason was on
// screen, in a panel that replaced the findings. The footer now says to look in
// the log, and this is what makes that true.
func recordStageError(result *Result, stage string, err error) {
	log.Printf("ERROR [scan/%s] stage failed: %v", stage, err)
	result.Errors = append(result.Errors, fmt.Sprintf("%s: %v", stage, err))
}

// CountFindings aggregates findings into separate counters by category and
// severity. Vulnerabilities are counted by severity into Counts; secrets,
// licenses and misconfigurations into their dedicated fields.
//
// The category comes from Categorize, which the results tabs also use — these
// counters and the tab labels are the same numbers, and used to be computed by
// two rules that disagreed (see category.go).
func (r *Result) CountFindings() {
	r.Counts = SeverityCounts{}
	r.SecretCount = 0
	r.LicenseCount = 0
	r.MisconfigCount = 0
	r.CIIssueCount = 0
	for _, f := range r.Findings {
		switch Categorize(f) {
		case CategorySecret:
			r.SecretCount++
		case CategoryLicense:
			r.LicenseCount++
		case CategoryMisconfiguration:
			r.MisconfigCount++
		case CategoryCIScore:
			r.CIIssueCount++
		case CategoryVulnerability:
			r.countBySeverity(f.Severity)
		}
	}
}

// countBySeverity adds one vulnerability to the severity histogram.
func (r *Result) countBySeverity(severity SeverityLevel) {
	switch severity {
	case SeverityCritical:
		r.Counts.Critical++
	case SeverityHigh:
		r.Counts.High++
	case SeverityMedium:
		r.Counts.Medium++
	case SeverityLow:
		r.Counts.Low++
	default:
		r.Counts.Unknown++
	}
}

// SecretVerdict is what this scan can say about secrets, for the caches and the
// columns that show a verdict rather than a count: nil when no stage looked,
// false when one looked and found nothing, true when one found something.
//
// It is the only verdict calculation in the application. There used to be
// two, both written as "a finding whose Source is gitleaks", and both became
// wrong the day Trivy started finding secrets too: a repo whose only secrets
// were Trivy's read as clean. SecretCount comes from Categorize, which is
// the only classifier (§3.11).
func (r *Result) SecretVerdict() *bool {
	if !r.SecretsScanned {
		return nil
	}
	found := r.SecretCount > 0
	return &found
}

// TotalFindings returns the total number of findings across all types
func (r *Result) TotalFindings() int {
	return r.Counts.Critical + r.Counts.High + r.Counts.Medium + r.Counts.Low + r.Counts.Unknown +
		r.SecretCount + r.LicenseCount + r.MisconfigCount + r.CIIssueCount
}

// ToolSource indicates how a tool is available
type ToolSource string

const (
	ToolSourceNone   ToolSource = "none"
	ToolSourceBinary ToolSource = "binary"
	// ToolSourceContainer runs the tool from an image, through whichever engine
	// is configured. It used to be ToolSourceDocker = "docker", which baked the
	// engine's name into a type the UI reads (§3.67). The rename is internal
	// only: this value is never serialised, and the configuration already spells
	// the same choice engine-neutrally (config.ToolSourceImage = "image").
	ToolSourceContainer ToolSource = "container"
)

// DependencyStatus holds the availability status of external tools
type DependencyStatus struct {
	TrivyAvailable    bool
	TrivySource       ToolSource
	TrivyVersion      string
	TrivyBinary       string // Executable to run when TrivySource is binary

	TrivyBinary       string // Executable to run when TrivySource is binary
	TrivyImage        string // OCI image used for Trivy
	GitleaksAvailable bool
	GitleaksSource    ToolSource
	GitleaksVersion   string
	GitleaksBinary    string // Executable to run when GitleaksSource is binary
	GitleaksImage     string // OCI image used for Gitleaks
	PlumberAvailable  bool
	PlumberSource     ToolSource
	PlumberVersion    string
	PlumberBinary     string // Executable to run when PlumberSource is binary
	PlumberImage      string // OCI image used for plumber

	// EngineAvailable reports whether the configured container engine answered.
	// Without it no image-sourced tool can run, whichever engine it is.
	EngineAvailable bool

	// ImageScanSocket is why an image scan in a container may be impossible
	// even when the engine is present: trivy inspects a host-held image through
	// the engine's socket, and rootless podman has none unless `podman system
	// service` is running. Empty means the mount cannot be made — see
	// ImageScanBlocked.
	ImageScanSocket string
}

// ImageScanBlocked reports why an image cannot be scanned in a container, or ""
// when it can.
//
// It answers before the keypress, which is what Rule 130 needs: the action is
// greyed out with this reason rather than attempted and failed. A directory
// scan mounts only the directory, so it stays available either way — the socket
// is the image path's problem alone.
func (d DependencyStatus) ImageScanBlocked(engineName string, server string) string {
	if d.ImageScanSocket != "" || server != "" {
		// A Trivy server does the inspection itself; no socket is needed.
		return ""
	}
	return engineName + " socket not found — run `" + engineName +
		" system service` or set a Trivy server"
}

// Default images for the container-sourced tools
const (
	DefaultTrivyImage    = "aquasec/trivy"
	DefaultGitleaksImage = "zricethezav/gitleaks"
	DefaultPlumberImage  = "getplumber/plumber"
)

// CheckDependencies works out where each scanner runs from, for one context's
// scan configuration.
//
// It replaces CheckDependenciesWithImages, which took only the two image names.
// That signature is why `trivy_path` and `gitleaks_path` were never read: there
// was nowhere to pass them (D27). Taking the whole ScanConfig also lets the
// per-tool source preference be honoured, which binary-first resolution made
// impossible to express.
func CheckDependencies(c config.ScanConfig) DependencyStatus {
	trivyImage := c.TrivyImage
	if trivyImage == "" {
		trivyImage = DefaultTrivyImage
	}
	gitleaksImage := c.GitleaksImage
	if gitleaksImage == "" {
		gitleaksImage = DefaultGitleaksImage
	}
	plumberImage := c.PlumberImage
	if plumberImage == "" {
		plumberImage = DefaultPlumberImage
	}

	status := DependencyStatus{
		TrivySource:    ToolSourceNone,
		TrivyImage:     trivyImage,
		GitleaksSource: ToolSourceNone,
		GitleaksImage:  gitleaksImage,
		PlumberSource:  ToolSourceNone,
		PlumberImage:   plumberImage,
	}

	if path, err := exec.LookPath(engine.Current().Binary); err == nil && path != "" {
		status.EngineAvailable = true
		status.ImageScanSocket = engine.Current().HostSocket()
	}

	trivy := resolveTool(c.TrivySource, c.TrivyPath, "trivy", trivyImage, status.EngineAvailable, "--version")
	status.TrivyAvailable = trivy.Available
	status.TrivySource = trivy.Source
	status.TrivyBinary = trivy.Binary
	status.TrivyVersion = trivy.Version

	gitleaks := resolveTool(c.GitleaksSource, c.GitleaksPath, "gitleaks", gitleaksImage, status.EngineAvailable, "version")
	status.GitleaksAvailable = gitleaks.Available
	status.GitleaksSource = gitleaks.Source
	status.GitleaksBinary = gitleaks.Binary
	status.GitleaksVersion = gitleaks.Version

	// `plumber version` writes the installed version to stdout and an upgrade
	// notice — "plumber v0.4.44 is available (you have 0.4.40)" — to stderr.
	// toolVersion reads stdout only, so the two cannot be confused; measured
	// rather than assumed, because reporting the available version as the
	// installed one is the kind of thing nobody notices for months.
	plumber := resolveTool(c.PlumberSource, c.PlumberPath, "plumber", plumberImage, status.EngineAvailable, "version")
	status.PlumberAvailable = plumber.Available
	status.PlumberSource = plumber.Source
	status.PlumberBinary = plumber.Binary
	status.PlumberVersion = plumber.Version

	return status
}

// imageIsLocal verifies that the engine already holds an image.
func imageIsLocal(image string) bool {
	cmd := exec.Command(engine.Current().Binary, "images", "-q", image) //nolint:gosec // the binary is a declared engine name or a configured path
	output, err := cmd.Output()
	if err != nil {
		return false
	}
	// If output is not empty, image exists
	return len(output) > 0
}

	result.Duration = result.EndTime.Sub(result.StartTime)
	result.CountFindings()
	return result, nil
}

// Scan performs a security scan on the target, running all enabled stages in parallel.
func (s *Scanner) Scan(ctx context.Context, target string, targetType TargetType) (*Result, error) {
	result := &Result{
		Target:     target,
		TargetType: targetType,
		StartTime:  time.Now(),
		Findings:   []Finding{},
		Errors:     []string{},
	}

	notify := func(update ProgressUpdate) {
		if s.options.OnProgress != nil {
			s.options.OnProgress(update)
		}
	}

	// A stage whose tool is missing is not started at all, so it leaves neither a
	// finding nor an error behind — and a result with neither is indistinguishable
	// from a clean scan. Recording the reason up front is what stops "nothing
	// looked at this image" being reported as "this image is fine" (§1.3 D20).
	result.Errors = append(result.Errors, s.missingToolErrors(targetType)...)

	// mu guards writes to result (Findings, Errors) from concurrent goroutines
	var mu sync.Mutex

	eg, egCtx := errgroup.WithContext(ctx)

	// Vuln scan (Trivy)
	if s.options.EnableVuln && s.deps.TrivyAvailable {
		eg.Go(func() error {
			notify(ProgressUpdate{Stage: "vuln", Label: "Vulnerabilities", Status: StageRunning})
			progressFn := func(detail string) {
				notify(ProgressUpdate{Stage: "vuln", Label: "Vulnerabilities", Status: StageRunning, Detail: detail})
			}
			cmd := GetTrivyCommand(target, targetType, false, s.deps.TrivySpec(), s.options.TrivyServer, s.options.IgnoreUnfixed, s.options.IgnoreEOL)
			log.Printf("Running: %s", cmd)
			findings, err := RunTrivy(egCtx, target, targetType, false, s.deps.TrivySpec(), s.options.TrivyServer, s.options.IgnoreUnfixed, s.options.IgnoreEOL, progressFn)
			mu.Lock()
			defer mu.Unlock()
			if err != nil {
				recordStageError(result, "trivy vuln", err)
				notify(ProgressUpdate{Stage: "vuln", Label: "Vulnerabilities", Status: StageError, Detail: err.Error()})
			} else {
				result.Findings = append(result.Findings, findings...)
				notify(ProgressUpdate{Stage: "vuln", Label: "Vulnerabilities", Status: StageDone})
			}
			return nil
		})
	}

	// License scan (Trivy, directory only)
	if s.options.EnableLicense && s.deps.TrivyAvailable && targetType == TargetDirectory {
		eg.Go(func() error {
			notify(ProgressUpdate{Stage: "license", Label: "Licenses", Status: StageRunning})
			progressFn := func(detail string) {
				notify(ProgressUpdate{Stage: "license", Label: "Licenses", Status: StageRunning, Detail: detail})
			}
			cmd := GetTrivyCommand(target, targetType, true, s.deps.TrivySpec(), s.options.TrivyServer, s.options.IgnoreUnfixed, s.options.IgnoreEOL)
			log.Printf("Running: %s", cmd)
			findings, err := RunTrivy(egCtx, target, targetType, true, s.deps.TrivySpec(), s.options.TrivyServer, s.options.IgnoreUnfixed, s.options.IgnoreEOL, progressFn)
			mu.Lock()
			defer mu.Unlock()
			if err != nil {
				recordStageError(result, "trivy license", err)
				notify(ProgressUpdate{Stage: "license", Label: "Licenses", Status: StageError})
			} else {
				result.Findings = append(result.Findings, findings...)
				notify(ProgressUpdate{Stage: "license", Label: "Licenses", Status: StageDone})
			}
			return nil
		})
	}

	// CI configuration score (plumber, directories only). An image has no
	// pipeline, so there is nothing to grade and the tab is empty on one.
	//
	// The target decides, not the batch: ciOptions reads this repository's own
	// remote and refuses one that is not this context's forge.
	if ciOpts, ok := s.ciOptions(target, targetType); ok {
		opts := ciOpts
		eg.Go(func() error {
			notify(ProgressUpdate{Stage: "ci", Label: "CI score", Status: StageRunning})
			progressFn := func(detail string) {
				notify(ProgressUpdate{Stage: "ci", Label: "CI score", Status: StageRunning, Detail: detail})
			}
			log.Printf("Running: %s", GetPlumberCommand(target, s.deps.PlumberSpec(), opts))
			report, err := RunPlumber(egCtx, target, s.deps.PlumberSpec(), opts, progressFn)
			mu.Lock()
			defer mu.Unlock()
			if err != nil {
				recordStageError(result, "plumber", err)
				notify(ProgressUpdate{Stage: "ci", Label: "CI score", Status: StageError, Detail: err.Error()})
				return nil
			}
			// CIScanned is written by a stage that succeeds, exactly as
			// SecretsScanned is — a withheld run counts as having looked, which
			// is why it is set here and Withheld is carried beside it rather
			// than instead of it.
			result.CIScanned = true
			result.CIScore = report.Score
			result.CIPoints = report.Points
			result.CIWithheld = report.Withheld
			result.CIReasons = report.Reasons
			result.CIMissing = report.CIMissing
			result.Findings = append(result.Findings, report.Findings...)
			notify(ProgressUpdate{Stage: "ci", Label: "CI score", Status: StageDone})
			return nil
		})
	}

	// Misconfig scan (Trivy)
	if s.options.EnableMisconfig && s.deps.TrivyAvailable {
		eg.Go(func() error {
			notify(ProgressUpdate{Stage: "misconfig", Label: "Misconfigurations", Status: StageRunning})
			progressFn := func(detail string) {
				notify(ProgressUpdate{Stage: "misconfig", Label: "Misconfigurations", Status: StageRunning, Detail: detail})
			}
			findings, err := RunTrivyMisconfig(egCtx, target, targetType, s.deps.TrivySpec(), s.options.TrivyServer, s.options.IgnoreEOL, progressFn)
			mu.Lock()
			defer mu.Unlock()
			if err != nil {
				recordStageError(result, "trivy misconfig", err)
				notify(ProgressUpdate{Stage: "misconfig", Label: "Misconfigurations", Status: StageError})
			} else {
				result.Findings = append(result.Findings, findings...)
				notify(ProgressUpdate{Stage: "misconfig", Label: "Misconfigurations", Status: StageDone})
			}
			return nil
		})
	}

	// Secret scan (Gitleaks, directory only)
	if s.options.EnableSecret && s.deps.GitleaksAvailable && targetType == TargetDirectory {
		eg.Go(func() error {
			notify(ProgressUpdate{Stage: "secret", Label: "Secrets (Gitleaks)", Status: StageRunning})
			progressFn := func(detail string) {
				notify(ProgressUpdate{Stage: "secret", Label: "Secrets (Gitleaks)", Status: StageRunning, Detail: detail})
			}
			cmd := GetGitleaksCommand(target, s.deps.GitleaksSpec(), s.options.GitleaksHistory, s.options.GitleaksConfig)
			log.Printf("Running: %s", cmd)
			findings, err := RunGitleaks(egCtx, target, s.deps.GitleaksSpec(), s.options.GitleaksHistory, s.options.GitleaksConfig, progressFn)
			mu.Lock()
			defer mu.Unlock()
			if err != nil {
				recordStageError(result, "gitleaks", err)
				notify(ProgressUpdate{Stage: "secret", Label: "Secrets (Gitleaks)", Status: StageError})
			} else {
				result.Findings = append(result.Findings, findings...)
				// A stage that succeeds is what makes the verdict known;
				// one that fails says nothing, and certainly not "clean".
				result.SecretsScanned = true
				notify(ProgressUpdate{Stage: "secret", Label: "Secrets (Gitleaks)", Status: StageDone})
			}
			return nil
		})
	}

	// Secret scan (Trivy). Both target types, unlike Gitleaks: this is what
	// gives an image scan a secret stage at all. The two are complementary
	// rather than redundant — Gitleaks reads git history, Trivy reads image
	// layers — so both run when the option is on and both tools are there.
	if s.options.EnableSecret && s.deps.TrivyAvailable {
		eg.Go(func() error {
			notify(ProgressUpdate{Stage: "trivy-secret", Label: "Secrets (Trivy)", Status: StageRunning})
			progressFn := func(detail string) {
				notify(ProgressUpdate{Stage: "trivy-secret", Label: "Secrets (Trivy)", Status: StageRunning, Detail: detail})
			}
			cmd := GetTrivySecretCommand(target, targetType, s.deps.TrivySpec(), s.options.TrivyServer)
			log.Printf("Running: %s", cmd)
			findings, err := RunTrivySecret(egCtx, target, targetType, s.deps.TrivySpec(), s.options.TrivyServer, progressFn)
			mu.Lock()
			defer mu.Unlock()
			if err != nil {
				recordStageError(result, "trivy secret", err)
				notify(ProgressUpdate{Stage: "trivy-secret", Label: "Secrets (Trivy)", Status: StageError})
			} else {
				result.Findings = append(result.Findings, findings...)
				result.SecretsScanned = true
				notify(ProgressUpdate{Stage: "trivy-secret", Label: "Secrets (Trivy)", Status: StageDone})
			}
			return nil
		})
	}

	// All goroutines return nil, so eg.Wait() never returns an error
	_ = eg.Wait()

	result.EndTime = time.Now()
	result.Duration = result.EndTime.Sub(result.StartTime)
	result.CountFindings()

	return result, nil
}

package output

import (
	"encoding/json"
	"fmt"
	"io"

	"github.com/yannh/kubeconform/pkg/validator"
)

type oresult struct {
	Filename         string                      `json:"filename"`
	Kind             string                      `json:"kind"`
	Name             string                      `json:"name"`
	Version          string                      `json:"version"`
	Status           string                      `json:"status"`
	Msg              string                      `json:"msg"`
	ValidationErrors []validator.ValidationError `json:"validationErrors,omitempty"`
}

type jsono struct {
	w                                   io.Writer
	withSummary                         bool
	verbose                             bool
	results                             []oresult
	nValid, nInvalid, nErrors, nSkipped int
}

// JSON will output the results of the validation as a JSON
func jsonOutput(w io.Writer, withSummary bool, isStdin, verbose bool) Output {
	return &jsono{
		w:           w,
		withSummary: withSummary,
		verbose:     verbose,
		results:     []oresult{},
		nValid:      0,
		nInvalid:    0,
		nErrors:     0,
		nSkipped:    0,
	}
}

// JSON.Write will only write when JSON.Flush has been called
func (o *jsono) Write(result validator.Result) error {
	msg, st := "", ""

	switch result.Status {
	case validator.Valid:
		st = "statusValid"
		o.nValid++
	case validator.Invalid:
		st = "statusInvalid"
		if result.Err != nil {
			msg = result.Err.Error()
		}
		o.nInvalid++
	case validator.Error:
		st = "statusError"
		if result.Err != nil {
			msg = result.Err.Error()
		}
		o.nErrors++
	case validator.Skipped:
		st = "statusSkipped"
		o.nSkipped++
	case validator.Empty:
	}

	if o.verbose || (result.Status != validator.Valid && result.Status != validator.Skipped && result.Status != validator.Empty) {
		sig, _ := result.Resource.Signature()
		o.results = append(o.results, oresult{
			Filename:         result.Resource.Path,
			Kind:             sig.Kind,
			Name:             sig.Name,
			Version:          sig.Version,
			Status:           st,
			Msg:              msg,
			ValidationErrors: result.ValidationErrors,
		})
	}

	return nil
}

// Flush outputs the results as JSON
func (o *jsono) Flush() error {
	var err error
	var res []byte

	if o.withSummary {
		jsonObj := struct {
			Resources []oresult `json:"resources"`
			Summary   struct {
				Valid   int `json:"valid"`
				Invalid int `json:"invalid"`
				Errors  int `json:"errors"`
				Skipped int `json:"skipped"`
			} `json:"summary"`
		}{
			Resources: o.results,
			Summary: struct {
				Valid   int `json:"valid"`
				Invalid int `json:"invalid"`
				Errors  int `json:"errors"`
				Skipped int `json:"skipped"`
			}{
				Valid:   o.nValid,
				Invalid: o.nInvalid,
				Errors:  o.nErrors,
				Skipped: o.nSkipped,
			},
		}

		res, err = json.MarshalIndent(jsonObj, "", "  ")
	} else {
		jsonObj := struct {
			Resources []oresult `json:"resources"`
		}{
			Resources: o.results,
		}
