	tc := kubeconformArgs("/repo", []string{"deploy/app.yaml"},
		ToolSpec{Source: ToolSourceContainer},
		KubeconformOptions{KubernetesVersion: "1.36.0", CacheDir: "/home/u/cache"})

	got := strings.Join(tc.Args, " ")
	for _, want := range []string{
